from solution import exchange
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(lst1, lst2):
    """Obviously-correct model: need at least as many evens in lst2 as odds in lst1."""
    odds_needed = sum(1 for x in lst1 if x % 2 != 0)
    evens_available = sum(1 for x in lst2 if x % 2 == 0)
    return "YES" if odds_needed <= evens_available else "NO"


# ---- concrete examples from the spec ----

def test_spec_example_yes():
    assert exchange([1, 2, 3, 4], [1, 2, 3, 4]) == "YES"


def test_spec_example_no():
    assert exchange([1, 2, 3, 4], [1, 5, 3, 4]) == "NO"


# ---- explicit differing-length cases (spec imposes no equal-length requirement) ----

def test_different_lengths_sufficient_evens_returns_yes():
    # 2 odds in lst1, 5 evens in lst2 -> possible
    assert exchange([1, 3], [2, 4, 6, 8, 10]) == "YES"


def test_different_lengths_already_all_even_returns_yes():
    # lst1 already all even, so YES regardless of lst2 contents/length
    assert exchange([2, 4], [1]) == "YES"
    assert exchange([2], [1, 3, 5]) == "YES"


def test_different_lengths_insufficient_evens_returns_no():
    # 3 odds needed, only 1 even available -> impossible
    assert exchange([1, 3, 5], [2, 1, 1]) == "NO"


def test_single_element_exchange_possible():
    assert exchange([1], [2]) == "YES"


def test_single_element_exchange_impossible():
    assert exchange([1], [3]) == "NO"


def test_already_all_even_ignores_lst2():
    assert exchange([2, 4, 6], [1, 3, 5]) == "YES"
    assert exchange([0, 8, 100], [7, 9]) == "YES"


# ---- property-based tests against reference model ----

@given(
    lst1=st.lists(st.integers(min_value=-100, max_value=100), min_size=1, max_size=8),
    lst2=st.lists(st.integers(min_value=-100, max_value=100), min_size=1, max_size=8),
)
def test_property_matches_reference_model_same_or_different_lengths(lst1, lst2):
    assert exchange(list(lst1), list(lst2)) == reference(lst1, lst2)


@given(
    n_odds=st.integers(min_value=1, max_value=5),
    n_evens=st.integers(min_value=1, max_value=5),
    extra=st.integers(min_value=0, max_value=3),
)
def test_property_odd_count_vs_even_count_boundary(n_odds, n_evens, extra):
    # lst1 has n_odds odds (+ maybe evens), lst2 has n_evens evens.
    # YES iff n_odds <= n_evens, regardless of lengths.
    lst1 = [1] * n_odds + [2] * extra
    lst2 = [2] * n_evens + [1] * extra
    assert exchange(list(lst1), list(lst2)) == ("YES" if n_odds <= n_evens else "NO")


@given(
    lst1=st.lists(st.integers(min_value=-50, max_value=50), min_size=1, max_size=6),
    lst2=st.lists(st.integers(min_value=-50, max_value=50), min_size=1, max_size=6),
)
def test_property_permutation_of_inputs_does_not_change_result(lst1, lst2):
    # Result depends only on counts, not order.
    assert exchange(list(reversed(lst1)), list(reversed(lst2))) == reference(lst1, lst2)
    assert exchange(list(sorted(lst1)), list(sorted(lst2))) == reference(lst1, lst2)


@given(
    lst1=st.lists(st.integers(min_value=-50, max_value=50), min_size=1, max_size=6),
    lst2=st.lists(st.integers(min_value=-50, max_value=50), min_size=1, max_size=6),
)
def test_property_adding_even_to_lst2_is_monotone(lst1, lst2):
    # Adding an even to lst2 can never turn YES into NO.
    r_before = reference(lst1, lst2)
    r_after = reference(lst1, lst2 + [2])
    if r_before == "YES":
        assert r_after == "YES"
    assert exchange(list(lst1), list(lst2) + [2]) == r_after
    # Adding an odd to lst1 needing one more even: check consistency
    assert exchange(list(lst1) + [1], list(lst2)) == reference(lst1 + [1], lst2)


@given(
    lst1=st.lists(st.integers(min_value=-20, max_value=20), min_size=1, max_size=5),
    lst2=st.lists(st.integers(min_value=-20, max_value=20), min_size=1, max_size=5),
)
def test_property_return_value_is_exact_yes_no_string(lst1, lst2):
    res = exchange(list(lst1), list(lst2))
    assert res in ("YES", "NO")
    assert res == res.strip()
    assert res == res.upper()
